import{_ as i,o as t,c as o,a2 as a}from"./chunks/framework.DJWFW3S-.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"en/api/includes/api/map-methods.md","filePath":"en/api/includes/api/map-methods.md"}'),r={name:"en/api/includes/api/map-methods.md"};function l(d,e,s,p,m,n){return t(),o("div",null,[...e[0]||(e[0]=[a('<details><summary>isLoaded()</summary><div><br><p>Whether the map is loaded or not.</p><p>Returns:</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>getContainer()</summary><div><br><p>Get map&#39;s container</p><p>Returns:</p><ul><li><code>HTMLElement</code></li></ul></div></details><details><summary>getSpatialReference()</summary><div><br><p>Get the spatial reference of the Map.</p><p>Returns:</p><ul><li><code>SpatialReference</code> map&#39;s spatial reference</li></ul></div></details><details><summary>setSpatialReference(ref)</summary><div><br><p>Change the spatial reference of the map. <br> A SpatialReference is a series of settings to decide the map presentation:<br></p><ol><li>the projection.<br></li><li>zoom levels and resolutions. <br></li><li>full extent.<br> There are some <a href="http://www.foo.com" target="_blank" rel="noreferrer">predefined spatial references</a>, and surely you can <a href="http://www.foo.com" target="_blank" rel="noreferrer">define a custom one.</a>.<br> SpatialReference can also be updated by map.config(&#39;spatialReference&#39;, spatialReference);</li></ol><p>Parameters:</p><ul><li>ref <code>SpatialReferenceType</code> spatial reference</li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul><p>Fires:</p><ul><li><code>Map#spatialreferencechange</code></li></ul></div></details><details><summary>onConfig(conf)</summary><div><br><p>Callback when any option is updated</p><p>Parameters:</p><ul><li>conf <code>{ [key: string]: any }</code> options to update</li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getProjection()</summary><div><br><p>Get the projection of the map. <br> Projection is an algorithm for map projection, e.g. well-known <a href="https://en.wikipedia.org/wiki/Mercator_projection" target="_blank" rel="noreferrer">Mercator Projection</a> <br> A projection must have 2 methods: <br></p><ol><li>project(coordinate) - project the input coordinate <br></li><li>unproject(coordinate) - unproject the input coordinate <br> Projection also contains measuring method usually extended from a measurer: <br></li><li>measureLength(coord1, coord2) - compute length between 2 coordinates. <br></li><li>measureArea(coords[]) - compute area of the input coordinates. <br></li><li>locate(coord, distx, disty) - compute the coordinate from the coord with xdist on axis x and ydist on axis y.</li></ol><p>Returns:</p><ul><li><code>Object</code></li></ul></div></details><details><summary>getFullExtent()</summary><div><br><p>Get map&#39;s full extent, which is defined in map&#39;s spatial reference. <br> eg: {&#39;left&#39;: -180, &#39;right&#39; : 180, &#39;top&#39; : 90, &#39;bottom&#39; : -90}</p><p>Returns:</p><ul><li><code>Extent</code></li></ul></div></details><details><summary>setCursor(cursor)</summary><div><br><p>Set map&#39;s cursor style, cursor style is same with CSS.</p><p>Parameters:</p><ul><li>cursor <code>string</code> cursor style</li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>resetCursor()</summary><div><br><p>Reset map&#39;s cursor style.</p><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getCenter()</summary><div><br><p>Get center of the map.</p><p>Returns:</p><ul><li><code>Coordinate</code></li></ul></div></details><details><summary>setCenter(center, padding?)</summary><div><br><p>Set a new center to the map.</p><p>Parameters:</p><ul><li>center <code>Coordinate</code></li><li>padding (optional) <code>MapPaddingType</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getSize()</summary><div><br><p>Get map&#39;s size (width and height) in pixel.</p><p>Returns:</p><ul><li><code>Size</code></li></ul></div></details><details><summary>getContainerExtent()</summary><div><br><p>Get container extent of the map</p><p>Returns:</p><ul><li><code>PointExtent</code></li></ul></div></details><details><summary>getGroundExtent()</summary><div><br><p>get Ground Extent for sky ,line ,polygon 2d render clip etc</p><p>Returns:</p><ul><li><code>PointExtent</code></li></ul></div></details><details><summary>getExtent()</summary><div><br><p>Get the geographical extent of map&#39;s current view extent.</p><p>Returns:</p><ul><li><code>Extent</code></li></ul></div></details><details><summary>getProjExtent()</summary><div><br><p>Get the projected geographical extent of map&#39;s current view extent.</p><p>Returns:</p><ul><li><code>Extent</code></li></ul></div></details><details><summary>getPrjExtent()</summary><div><br><p>Alias for getProjExtent</p><p>Returns:</p><ul><li><code>Extent</code></li></ul></div></details><details><summary>getMaxExtent()</summary><div><br><p>Get the max extent that the map is restricted to.</p><p>Returns:</p><ul><li><code>Extent</code></li></ul></div></details><details><summary>setMaxExtent(extent)</summary><div><br><p>Sets the max extent that the map is restricted to.</p><p>Parameters:</p><ul><li>extent <code>Extent</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getZoom()</summary><div><br><p>Get map&#39;s current zoom.</p><p>Returns:</p><ul><li><code>Number</code></li></ul></div></details><details><summary>getZoomForScale(scale, fromZoom?, isFraction?)</summary><div><br><p>Caculate the target zoom if scaling from &quot;fromZoom&quot; by &quot;scale&quot;</p><p>Parameters:</p><ul><li>scale <code>number</code></li><li>fromZoom (optional) <code>number</code></li><li>isFraction (optional) <code>boolean</code> can return fractional zoom</li></ul><p>Returns:</p><ul><li><code>Number</code> zoom fit for scale starting from fromZoom</li></ul></div></details><details><summary>getZoomFromRes(res)</summary><div><br><p>Get the zoom for a resolution, clamped to minZoom and maxZoom</p><p>Parameters:</p><ul><li>res <code>number</code></li></ul><p>Returns:</p><ul><li><code>number</code></li></ul></div></details><details><summary>setZoom(zoom, options = { &#39;animation&#39;: true })</summary><div><br><p>Sets zoom of the map</p><p>Parameters:</p><ul><li>zoom <code>number</code></li><li>options = { &#39;animation&#39;: true } <code>Any</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getMaxZoom()</summary><div><br><p>Get the max zoom that the map can be zoom to.</p><p>Returns:</p><ul><li><code>Number</code></li></ul></div></details><details><summary>setMaxZoom(maxZoom)</summary><div><br><p>Sets the max zoom that the map can be zoom to.</p><p>Parameters:</p><ul><li>maxZoom <code>number</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getMinZoom()</summary><div><br><p>Get the min zoom that the map can be zoom to.</p><p>Returns:</p><ul><li><code>Number</code></li></ul></div></details><details><summary>setMinZoom(minZoom)</summary><div><br><p>Sets the min zoom that the map can be zoom to.</p><p>Parameters:</p><ul><li>minZoom <code>number</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getMaxNativeZoom()</summary><div><br><p>Maximum zoom the map has</p><p>Returns:</p><ul><li><code>Number</code></li></ul></div></details><details><summary>getGLRes()</summary><div><br><p>Resolution for world point in WebGL context</p><p>Returns:</p><ul><li><code>Number</code></li></ul></div></details><details><summary>getGLScale(zoom?)</summary><div><br><p>Caculate scale from gl zoom to given zoom (default by current zoom)</p><p>Parameters:</p><ul><li>zoom (optional) <code>number</code> =undefined] target zoom, current zoom by default</li></ul><p>Returns:</p><ul><li><code>Number</code></li></ul></div></details><details><summary>zoomIn()</summary><div><br><p>zoom in</p><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>zoomOut()</summary><div><br><p>zoom out</p><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>isZooming()</summary><div><br><p>Whether the map is zooming</p><p>Returns:</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>isInteracting()</summary><div><br><p>Whether the map is being interacted</p><p>Returns:</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>setCenterAndZoom(center, zoom?, padding?)</summary><div><br><p>Sets the center and zoom at the same time.</p><p>Parameters:</p><ul><li>center <code>Coordinate</code></li><li>zoom (optional) <code>number</code></li><li>padding (optional) <code>MapPaddingType</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>getFitZoom(extent, isFraction?, padding?)</summary><div><br><p>Caculate the zoom level that contains the given extent with the maximum zoom level possible.</p><p>Parameters:</p><ul><li>extent <code>Extent</code></li><li>isFraction (optional) <code>boolean</code> can return fractional zoom</li><li>padding (optional) <code>MapPaddingType</code> [padding] - padding</li></ul><p>Returns:</p><ul><li><code>Number</code> zoom fit for scale starting from fromZoom</li></ul></div></details><details><summary>getView()</summary><div><br><p>Get map&#39;s current view (center/zoom/pitch/bearing)</p><p>Returns:</p><ul><li><code>Object</code> { center : *, zoom : *, pitch : *, bearing : * }</li></ul></div></details><details><summary>stringifyView()</summary><div><br><p>Serialize the current map view into a JSON string</p></div></details><details><summary>setView(view)</summary><div><br><p>Set map&#39;s center/zoom/pitch/bearing at one time</p><p>Parameters:</p><ul><li>view <code>MapViewType</code> a object containing center/zoom/pitch/bearing return {Map} this</li></ul></div></details><details><summary>getResolution(zoom?)</summary><div><br><p>Get map&#39;s resolution</p><p>Parameters:</p><ul><li>zoom (optional) <code>number</code> zoom or current zoom if not given</li></ul><p>Returns:</p><ul><li><code>Number</code> resolution</li></ul></div></details><details><summary>getScale(zoom?)</summary><div><br><p>Get scale of resolutions from zoom to max zoom</p><p>Parameters:</p><ul><li>zoom (optional) <code>number</code> zoom or current zoom if not given</li></ul><p>Returns:</p><ul><li><code>Number</code> scale</li></ul></div></details><details><summary>fitExtent(extent, zoomOffset?, options?, step?)</summary><div><br><p>Set the map to be fit for the given extent with the max zoom level possible.</p><p>Parameters:</p><ul><li>extent <code>ExtentLike</code> extent</li><li>zoomOffset (optional) <code>number</code> zoom offset</li><li>options (optional) <code>MapFitType</code> ={}] - options</li><li>step (optional) <code>(frame) =&gt; void</code> step function for animation</li></ul><p>Returns:</p><ul><li><code>Map | player</code> - this</li></ul></div></details><details><summary>getBaseLayer()</summary><div><br><p>Get the base layer of the map.</p><p>Returns:</p><ul><li><code>Layer</code></li></ul></div></details><details><summary>setBaseLayer(baseLayer)</summary><div><br><p>Sets a new base layer to the map.<br> Some events will be thrown such as baselayerchangestart, baselayerload, baselayerchangeend.</p><p>Parameters:</p><ul><li>baseLayer <code>Layer</code> new base layer</li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul><p>Fires:</p><ul><li><code>Map#setbaselayer</code></li><li><code>Map#baselayerchangestart</code></li><li><code>Map#baselayerchangeend</code></li></ul></div></details><details><summary>removeBaseLayer()</summary><div><br><p>Remove the base layer from the map</p><p>Returns:</p><ul><li><code>Map</code> this</li></ul><p>Fires:</p><ul><li><code>Map#baselayerremove</code></li></ul></div></details><details><summary>getLayers(filter?)</summary><div><br><p>Get the layers of the map, except base layer (which should be by getBaseLayer). <br> A filter function can be given to filter layers, e.g. exclude all the VectorLayers.</p><p>Parameters:</p><ul><li>filter (optional) <code>(layer: Layer) =&gt; boolean</code> =undefined] - a filter function of layers, return false to exclude the given layer.</li></ul><p>Returns:</p><ul><li><code>Layer[]</code></li></ul></div></details><details><summary>getLayer(id)</summary><div><br><p>Get the layer with the given id.</p><p>Parameters:</p><ul><li>id <code>string</code> layer id</li></ul><p>Returns:</p><ul><li><code>Layer</code></li></ul></div></details><details><summary>addLayer(layers, otherLayers)</summary><div><br><p>Add a new layer on the top of the map.</p><p>Parameters:</p><ul><li>layers <code>Layer | Array&lt;Layer&gt;</code></li><li>otherLayers <code>Array&lt;Layer&gt;</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul><p>Fires:</p><ul><li><code>Map#addlayer</code></li></ul></div></details><details><summary>removeLayer(layers)</summary><div><br><p>Remove a layer from the map</p><p>Parameters:</p><ul><li>layers <code>Layer | Array&lt;Layer&gt;</code> one or more layers or layer ids</li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul><p>Fires:</p><ul><li><code>Map#removelayer</code></li></ul></div></details><details><summary>sortLayers(layers)</summary><div><br><p>Sort layers according to the order provided, the last will be on the top.</p><p>Parameters:</p><ul><li>layers <code>Array&lt;Layer&gt;</code> layers or layer ids to sort</li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>toDataURL(options?)</summary><div><br><p>Exports image from the map&#39;s canvas.</p><p>Parameters:</p><ul><li>options (optional) <code>MapDataURLType</code> =undefined] - options</li></ul><p>Returns:</p><ul><li><code>String</code> image of base64 format.</li></ul></div></details><details><summary>coordToPoint(coordinate, zoom?, out?)</summary><div><br><p>shorter alias for coordinateToPoint</p><p>Parameters:</p><ul><li>coordinate <code>Coordinate</code></li><li>zoom (optional) <code>number</code></li><li>out (optional) <code>Point</code></li></ul></div></details><details><summary>coordToPointAtRes(coordinate, res?, out?)</summary><div><br><p>shorter alias for coordinateToPointAtRes</p><p>Parameters:</p><ul><li>coordinate <code>Coordinate</code></li><li>res (optional) <code>number</code></li><li>out (optional) <code>Point</code></li></ul></div></details><details><summary>pointToCoord(point, zoom?, out?)</summary><div><br><p>shorter alias for pointToCoordinate</p><p>Parameters:</p><ul><li>point <code>Point</code></li><li>zoom (optional) <code>number</code></li><li>out (optional) <code>Coordinate</code></li></ul></div></details><details><summary>pointAtResToCoord(point, res?, out?)</summary><div><br><p>shorter alias for pointAtResToCoordinate</p><p>Parameters:</p><ul><li>point <code>Point</code></li><li>res (optional) <code>number</code></li><li>out (optional) <code>Coordinate</code></li></ul></div></details><details><summary>coordToViewPoint(coordinate, out?, altitude?)</summary><div><br><p>shorter alias for coordinateToViewPoint</p><p>Parameters:</p><ul><li>coordinate <code>Coordinate</code></li><li>out (optional) <code>Point</code></li><li>altitude (optional) <code>number</code></li></ul></div></details><details><summary>viewPointToCoord(viewPoint, out?)</summary><div><br><p>shorter alias for viewPointToCoordinate</p><p>Parameters:</p><ul><li>viewPoint <code>Point</code></li><li>out (optional) <code>Coordinate</code></li></ul></div></details><details><summary>coordToContainerPoint(coordinate, zoom?, out?)</summary><div><br><p>shorter alias for coordinateToContainerPoint</p><p>Parameters:</p><ul><li>coordinate <code>Coordinate</code></li><li>zoom (optional) <code>number</code></li><li>out (optional) <code>Point</code></li></ul></div></details><details><summary>containerPointToCoord(containerPoint, out?)</summary><div><br><p>shorter alias for containerPointToCoordinate</p><p>Parameters:</p><ul><li>containerPoint <code>Point</code></li><li>out (optional) <code>Coordinate</code></li></ul></div></details><details><summary>containerPointToViewPoint(containerPoint, out?)</summary><div><br><p>Converts a container point to the view point. Usually used in plugin development.</p><p>Parameters:</p><ul><li>containerPoint <code>Point</code></li><li>out (optional) <code>Point</code> =undefined] - optional point to receive result</li></ul><p>Returns:</p><ul><li><code>Point</code></li></ul></div></details><details><summary>viewPointToContainerPoint(viewPoint, out?)</summary><div><br><p>Converts a view point to the container point. Usually used in plugin development.</p><p>Parameters:</p><ul><li>viewPoint <code>Point</code></li><li>out (optional) <code>Point</code> =undefined] - optional point to receive result</li></ul><p>Returns:</p><ul><li><code>Point</code></li></ul></div></details><details><summary>checkSize(force?)</summary><div><br><p>Checks if the map container size changed and updates the map if so.</p><p>Parameters:</p><ul><li>force (optional) <code>boolean</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul><p>Fires:</p><ul><li><code>Map#resize</code></li></ul></div></details><details><summary>locate(coordinate, dx, dy)</summary><div><br><p>Computes the coordinate from the given meter distance.</p><p>Parameters:</p><ul><li>coordinate <code>Coordinate</code> source coordinate</li><li>dx <code>number</code> meter distance on X axis</li><li>dy <code>number</code> meter distance on Y axis</li></ul><p>Returns:</p><ul><li><code>Coordinate</code> Result coordinate</li></ul></div></details><details><summary>getMainPanel()</summary><div><br><p>Return map&#39;s main panel</p><p>Returns:</p><ul><li><code>HTMLElement</code></li></ul></div></details><details><summary>getPanels()</summary><div><br><p>Returns map panels.</p><p>Returns:</p><ul><li><code>Object</code></li></ul></div></details><details><summary>remove()</summary><div><br><p>Remove the map</p><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>isRemoved()</summary><div><br><p>whether the map is removed</p><p>Returns:</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>isMoving()</summary><div><br><p>Whether the map is moving</p><p>Returns:</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>onMoving(param)</summary><div><br><p>Moving callback firing the moving event and limiting max extent</p><p>Parameters:</p><ul><li>param <code>Any</code></li></ul></div></details><details><summary>onMoveEnd(param)</summary><div><br><p>Move end callback firing moveend and resetting cursor and center</p><p>Parameters:</p><ul><li>param <code>Any</code></li></ul></div></details><details><summary>onDragRotateStart(param)</summary><div><br><p>Set the drag rotating flag and fire the dragrotatestart event</p><p>Parameters:</p><ul><li>param <code>Any</code></li></ul></div></details><details><summary>onDragRotating(param)</summary><div><br><p>Fire the dragrotating event while the map is drag rotated</p><p>Parameters:</p><ul><li>param <code>Any</code></li></ul></div></details><details><summary>onDragRotateEnd(param)</summary><div><br><p>Clear the drag rotating flag and fire the dragrotateend event</p><p>Parameters:</p><ul><li>param <code>Any</code></li></ul></div></details><details><summary>isDragRotating()</summary><div><br><p>Whether the map is currently being drag rotated</p></div></details><details><summary>isOffscreen(box, viewportPadding = 0)</summary><div><br><p>Test if given box is out of current screen</p><p>Parameters:</p><ul><li>box <code>PointExtent | Array&lt;number&gt;</code> [minx, miny, maxx, maxy]</li><li>viewportPadding = 0 <code>Number</code> test padding</li></ul><p>Returns:</p><ul><li><code>Boolean</code></li></ul></div></details><details><summary>getRenderer()</summary><div><br><p>Returns the renderer instance of the map.</p></div></details><details><summary>getDevicePixelRatio()</summary><div><br><p>Get map&#39;s devicePixelRatio, you can override it by setting devicePixelRatio in options.</p><p>Returns:</p><ul><li><code>Number</code></li></ul></div></details><details><summary>setDevicePixelRatio(dpr)</summary><div><br><p>Set map&#39;s devicePixelRatio</p><p>Parameters:</p><ul><li>dpr <code>number</code></li></ul><p>Returns:</p><ul><li><code>Map</code> this</li></ul></div></details><details><summary>setContainerDomRect(domRect)</summary><div><br><p>Set the container DOM content rect used to compute the map size</p><p>Parameters:</p><ul><li>domRect <code>DOMRect</code></li></ul></div></details><details><summary>offsetPlatform(offset?)</summary><div><br><p>Gets map panel&#39;s current view point.</p><p>Parameters:</p><ul><li>offset (optional) <code>Point</code></li></ul><p>Returns:</p><ul><li><code>Point</code></li></ul></div></details><details><summary>getViewPoint()</summary><div><br><p>Get map&#39;s view point, adding in frame offset</p><p>Returns:</p><ul><li><code>Point</code> map view point</li></ul></div></details><details><summary>toJSON(options?)</summary><div><br><p>Export the map&#39;s json, a snapshot of the map in JSON format.<br> It can be used to reproduce the instance by fromJSON method</p><p>Parameters:</p><ul><li>options (optional) <code>MapOptionsType</code> =null] - export options</li></ul><p>Returns:</p><ul><li><code>Object</code> layer&#39;s JSON</li></ul></div></details>',82)])])}const y=i(r,[["render",l]]);export{c as __pageData,y as default};
